class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        changes = {5: 0, 10: 0}

        for bill in bills:
            if bill == 5:
                changes[5] += 1
            elif bill == 10:
                changes[10] += 1
                changes[5] -= 1
            else:
                if changes[10] > 0:
                    changes[5] -= 1
                    changes[10] -= 1
                else:
                    changes[5] -= 3

            if changes[5] < 0:
                return False
            elif changes[10] < 0:
                return False

        return True
